contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount, address recipient) public payable {
        require(address(this).balance >= amount);
        c.f{value: amount}("");
        uint256 balBefore = address(c).balance;
        bool reverted;
        if (msg.sender == address(this)) {
            // msg.sender to c is this test contract, which is not the owner
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
            assert(reverted && address(c).balance == balBefore);
        } else {
            assert(true);
        }
    }
    receive() external payable {}
}
